    d.push({url: 'about:blank#autoCache#', desc: '216&&list', col_type: 'x5_webview_single', extra: {js: $.toString(function(page, json, ruleMeta) { document.documentElement.innerHTML = page; var data = []; var meta = {}; try { data = JSON.parse(json || '[]'); } catch (e) {} try { meta = JSON.parse(ruleMeta || '{}'); } catch (e2) {} if (!data || !data.length) return; var root = document.getElementById('carousel'); var current = 0; var nodes = []; function escapeText(value) { return String(value || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); } function update() { var total = nodes.length; for (var i = 0; i < total; i++) { var offset = (i - current + total) % total; nodes[i].className = 'item'; if (offset === 0) nodes[i].className += ' center'; else if (offset === 1) nodes[i].className += ' right'; else if (offset === total - 1) nodes[i].className += ' left'; else if (offset === 2) nodes[i].className += ' far-right'; else if (offset === total - 2) nodes[i].className += ' far-left'; } } function move(step) { current = (current + step + nodes.length) % nodes.length; update(); } for (var i = 0; i < data.length; i++) { (function(item) { var node = document.createElement('div'); node.className = 'item'; node.innerHTML = '<img src="' + escapeText(item.img) + '"><p>' + escapeText(item.title) + '</p>'; node.onclick = function() { if (!item.url) return; var url = String(item.url); var findRule = ''; var ruleAt = url.indexOf('@rule='); if (ruleAt > -1) { findRule = url.substring(ruleAt + 6); url = url.substring(0, ruleAt); } fba.open(JSON.stringify({rule: meta.title || '', title: item.title || '详情', url: url, group: meta.group || '', col_type: '', findRule: findRule, preRule: meta.preRule || '', pages: meta.pages || '', extra: {}})); }; root.appendChild(node); nodes.push(node); })(data[i]); } update(); if (nodes.length > 1) setInterval(function() { move(1); }, 3000); }, html, JSON.stringify(items), JSON.stringify(ruleMeta)), j