  njPicB64: function(url) {
    var u = String(url || '').trim();
    if (!u) { return ''; }
    if (u.indexOf('data:') === 0) { return u; }
    var local = u;
    if (u.indexOf('http') === 0 || u.indexOf('//') === 0) { local = this.njPic(u); }
    if (!local) { return ''; }
    if (local.indexOf('http') === 0 || local.indexOf('data:') === 0) { return local; }
    try {
      var lp = String(local);
      var rp = lp;
      if (rp.indexOf('file://') === 0) { rp = rp.substring(7); }
      else if (rp.indexOf('file:') === 0) { rp = rp.substring(5); }
      var f = new java.io.File(rp);
      if (!f.exists()) { return local; }
      var fis = new java.io.FileInputStream(f);
      var baos = new java.io.ByteArrayOutputStream();
      var buf = java.lang.reflect.Array.newInstance(java.lang.Byte.TYPE, 8192);
      var k = 0;
      while ((k = fis.read(buf, 0, 8192)) > 0) { baos.write(buf, 0, k); }
      fis.close();
      var bytes = baos.toByteArray();
      if (!bytes || bytes.length < 10) { return local; }
