      if (!b64) { return local; }
      var b0 = bytes[0]; if (b0 < 0) { b0 += 256; }
      var b1 = bytes.length > 1 ? bytes[1] : 0; if (b1 < 0) { b1 += 256; }
      var mime = 'image/jpeg';
      if (b0 === 0x89 && b1 === 0x50) { mime = 'image/png'; }
      else if (b0 === 0x52 && b1 === 0x49) { mime = 'image/webp'; }
      else if (b0 === 0x47 && b1 === 0x49) { mime = 'image/gif'; }
      return 'data:' + mime + ';base64,' + b64;
    } catch (e) { return local; }
